-- ============================================================
-- 인블루 · 019 게시글 작성순번 (2026-11-22)
-- Supabase SQL Editor 에서 전체를 실행하세요. (001 ~ 018 실행 후)
-- 여러 번 실행해도 안전합니다.
--
-- 더하는 것
--   1) posts · zone_reviews · user_foods · user_parkings 에
--      post_no bigint generated by default as identity 컬럼 추가
--   2) 이미 있는 글은 created_at asc, id asc 순서로 1, 2, 3 … 번호를 채움
--      (번호는 컬럼을 처음 만들 때 한 번만 매깁니다. 다시 실행해도
--       이미 매긴 번호는 그대로 두어 작성순번이 영구히 유지됩니다)
--   3) 각 identity 시퀀스의 다음 값을 coalesce(max(post_no), 0) + 1 로 맞춤
--   4) anon / authenticated 가 post_no 를 읽고 새 글에서 번호를 받을 수 있게 권한 확인
-- ============================================================

-- ------------------------------------------------------------
-- 1. posts (라팍톡 피드)
-- ------------------------------------------------------------
do $$
begin
  if not exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'posts' and column_name = 'post_no'
  ) then
    alter table public.posts add column post_no bigint generated by default as identity;

    with ordered as (
      select id, row_number() over (order by created_at asc, id asc) as rn
        from public.posts
    )
    update public.posts p
       set post_no = o.rn
      from ordered o
     where p.id = o.id;
  end if;
end $$;

comment on column public.posts.post_no is '게시글 작성순번 — 화면에 No.N 으로 표시. 지워지지 않고 새 글마다 1씩 증가';

select setval(
  pg_get_serial_sequence('public.posts', 'post_no'),
  coalesce((select max(post_no) from public.posts), 0) + 1,
  false
);

