-- ------------------------------------------------------------
-- 5. 권한 — 007 의 권한이 이미 있으면 그대로, 없으면 채웁니다.
--    (테이블 grant 는 컬럼 전체에 적용되므로 새 컬럼 post_no 도 함께 읽힙니다)
--    identity 시퀀스는 새 글 insert 시 nextval 이 필요합니다.
-- ------------------------------------------------------------
grant select on public.posts, public.zone_reviews, public.user_foods, public.user_parkings
  to anon, authenticated;
grant usage, select on all sequences in schema public to anon, authenticated;

-- PostgREST 스키마 캐시를 새로 읽어 post_no 를 바로 인식하게 합니다.
notify pgrst, 'reload schema';

-- ------------------------------------------------------------
-- 6. 확인용 (실행 결과 탭에 표로 남습니다)
-- ------------------------------------------------------------
select 'posts' as table_name, count(*) as row_count, coalesce(max(post_no), 0) as last_no
  from public.posts
union all
select 'zone_reviews', count(*), coalesce(max(post_no), 0) from public.zone_reviews
union all
select 'user_foods', count(*), coalesce(max(post_no), 0) from public.user_foods
union all
select 'user_parkings', count(*), coalesce(max(post_no), 0) from public.user_parkings
order by 1;
